SELECT md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, COALESCE(di.efo_term, di.mesh_heading) AS indication_label, di.max_phase_for_ind FROM molecule_dictionary md JOIN drug_indication di ON di.molregno = md.molregno JOIN compound_structures cs ON cs.molregno = md.molregno WHERE md.max_phase = 4 AND (di.efo_term LIKE '%COVID-19%' OR di.mesh_heading LIKE '%COVID-19%') ORDER BY md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id, COALESCE(di.efo_term, di.mesh_heading), di.max_phase_for_ind
